function foldElement(el,title,idx){let parent=el.parentNode,box=document.createElement('details'),summary=document.createElement('summary'),id=`cc-fold-${idx}`,key=`cc-fold-state:${page}:${page==='cppunit'?cppCurrent:current}:${id}`;box.className='cc-lesson-fold';box.id=id;summary.textContent=title;box.append(summary);parent.insertBefore(box,el);box.append(el);try{box.open=sessionStorage.getItem(key)==='open'}catch(_){}box.addEventListener('toggle',()=>{try{sessionStorage.setItem(key,box.open?'open':'closed')}catch(_){}scheduleToc()});return box}
